    "difficulty": "medium",
    "questionEn": "Dative Verb Syntactic Government: \"Wie steht ______ das Kleid?\" — \"Es steht ______ fantastisch!\" Which pair of personal pronouns in dative is correct?",
    "questionAr": "أفعال الداتيف والضمائر الشخصية: \"Wie steht ______ das Kleid؟\" — \"Es steht ______ fantastisch!\" أي زوج من ضمائر الداتيف يكمل الفراغ بدقة؟",
    "optionsEn": [
      "dich / mich (Accusative error with dative verb stehen)",
      "dir / mir (Correct 2nd person and 1st person dative pronouns)",
      "du / ich (Nominative subject error with verb of aesthetic appeal)",
      "ihr / sie (Mixed case third-person misalignment)"
    ],
    "optionsAr": [
      "dich / mich (مشتت: ضمائر نصب خاطئة مع فعل يستلزم الداتيف)",
      "dir / mir (صحيح: ضميرا المخاطب والمتكلم في حالة الداتيف مع فعل stehen)",
      "du / ich (مشتت: ضمائر رفع فاعل بينما الفعل يستلزم مفعول داتيف)",
      "ihr / sie (مشتت: خلط في الضمائر والحالات الإعرابية)"
    ],
    "correctIndex": 1,
    "correctAnswer": "dir / mir (Correct 2nd person and 1st person dative pronouns)",
    "hintEn": "Recall the governing linguistic rules of Lektion 12: Kleidung, Einkaufen & Dienstleistungen and consider case endings and sentence syntax.",
    "hintAr": "تذكر القواعد النحوية واللغوية للدرس (الدرس الثاني عشر: الملابس، التسوق وخدمة العملاء) ودقق في علامات الحالات الإعرابية وبناء الجملة.",
    "stepByStepSolutionEn": [
      "Analyze question context and target grammatical/situational objective.",
      "Evaluate option morphology, agreement (Genus, Kasus, Numerus), and word order.",
      "Confirm dir / mir (Correct 2nd person and 1st person dative pronouns) aligns precisely with official standards."
    ],
    "stepByStepSolutionAr": [
      "تحليل سياق السؤال وتحديد القاعدة النحوية أو الموقف المستهدف بدقة.",
      "مطابقة النهايات الإعرابية (نوع الاسم وحالته الإعرابية من رفع أو نصب أو جر) وموقع الفعل.",
      "اختيار البديل الصحيح: dir / mir (صحيح: ضميرا المخاطب والمتكلم في حالة الداتيف مع فعل stehen)."
    ],
    "teacherTipEn": "In Egyptian ministerial examinations, always identify the subject (Nominativ) first before assigning case endings!",
    "teacherTipAr": "نصيحة معلم الثانوية العامة: حدد فاعل الجملة أولاً قبل تطبيق نهايات النصب أو الجر، وانتبه لأقواس الأفعال في نهاية الجملة!",
    "explanationEn": "Correct answer is: \"dir / mir (Correct 2nd person and 1st person dative pronouns)\". It strictly satisfies German syntax and communicative benchmarks.",
    "explanationAr": "الإجابة الصحيحة هي: \"dir / mir (صحيح: ضميرا المخاطب والمتكلم في حالة الداتيف مع فعل stehen)\". وتتوافق بدقة مع معايير وزارة التربية والتعليم وامتحانات الثانوية العامة."
