    "correctIndex": 2,
    "correctAnswer": "dir / mir (Correct 2nd person and 1st person dative pronouns)",
    "hintEn": "Recall the governing linguistic rules of Lektion 12: Kleidung, Einkaufen & Dienstleistungen and consider case endings and sentence syntax.",
